mapper.select:
SELECT t.tool_id, t.tool_code, t.tool_name, t.display_alias, t.tool_type, t.status, t.revision, t.latest_version_id, t.latest_version_no, t.latest_readiness, v.exposed_name, v.description, v.read_only, ( SELECT count(DISTINCT a.agent_id) FROM squad_chat.sq_agent a JOIN squad_chat.sq_agent_version_tool b ON b.agent_version_id = a.latest_version_id WHERE a.deleted_at IS NULL AND b.tool_id = t.tool_id ) AS usage_count, t.last_update_time FROM squad_chat.sq_tool t LEFT JOIN squad_chat.sq_tool_version v ON v.tool_version_id = t.latest_version_id WHERE t.deleted_at IS NULL
AND t.tool_id = #{toolId}
ORDER BY t.last_update_time DESC, t.id DESC
